CREATE OR REPLACE FUNCTION public.local_feed_rows(p_country text, p_region text DEFAULT NULL::text)
 RETURNS TABLE(kind text, id uuid, happened_at timestamp with time zone)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select 'car'::text, c.id, c.created_at
    from public.cars c
    join public.profiles p on p.id = c.owner_id
   where c.is_public
     and p.country = p_country
     and (p_region is null or p.region = p_region)
  union all
  select 'update'::text, a.id, a.published_at
    from public.activity_posts a
    left join public.cars c on c.id = a.car_id
    join public.profiles p on p.id = a.author_id
   where a.published_at is not null
     and (a.car_id is null or c.is_public)
     and p.country = p_country
     and (p_region is null or p.region = p_region)
  union all
  select 'part'::text, l.id, l.created_at
    from public.listings l
    join public.profiles p on p.id = l.seller_id
   where l.status = 'active'
     and p.country = p_country
     and (p_region is null or p.region = p_region)
  order by 3 desc, 2 desc;
$function$;

grant execute on function public.local_feed_rows(p_country text, p_region text) to authenticated;
grant execute on function public.local_feed_rows(p_country text, p_region text) to service_role;
